// Extrair contexto da mensagem
const contexto = JSON.parse($json.contexto);
const mensagem = contexto.mensagem_original;
const cliente = contexto.dados_entrada.cliente;
const canal = contexto.canal;

// Determinar etapa da conversa
let etapa_conversa = 'saudacao';
let dados_coletados = {};

if (cliente) {
  // Cliente existente - verificar dados faltantes
  dados_coletados = {
    nome: cliente.nome,
    telefone: cliente.telefone,
    email: cliente.email,
    tipo_interesse: cliente.tipo_interesse,
    localizacao_preferida: cliente.localizacao_preferida,
    valor_maximo: cliente.valor_maximo
  };

  // Determinar próxima etapa baseada nos dados faltantes
  if (!dados_coletados.tipo_interesse) {
    etapa_conversa = 'tipo_interesse';
  } else if (!dados_coletados.localizacao_preferida) {
    etapa_conversa = 'localizacao';
  } else if (!dados_coletados.valor_maximo) {
    etapa_conversa = 'valor';
  } else if (!dados_coletados.nome || dados_coletados.nome.split(' ').length < 2) {
    etapa_conversa = 'nome_completo';
  } else {
    etapa_conversa = 'dados_completos';
  }
} else {
  // Cliente novo - começar do início
  etapa_conversa = 'saudacao';
}

// Analisar mensagem para extrair informações
const mensagemLower = mensagem.toLowerCase();

// Detectar tipo de interesse
if (mensagemLower.includes('comprar') || mensagemLower.includes('compra')) {
  dados_coletados.tipo_interesse = 'compra';
} else if (mensagemLower.includes('alugar') || mensagemLower.includes('aluguel')) {
  dados_coletados.tipo_interesse = 'aluguel';
} else if (mensagemLower.includes('vender') || mensagemLower.includes('venda')) {
  dados_coletados.tipo_interesse = 'venda';
}

// Detectar tipo de imóvel
let tipo_imovel = null;
if (mensagemLower.includes('casa')) tipo_imovel = 'casa';
else if (mensagemLower.includes('apartamento') || mensagemLower.includes('apto')) tipo_imovel = 'apartamento';
else if (mensagemLower.includes('terreno')) tipo_imovel = 'terreno';
else if (mensagemLower.includes('comercial') || mensagemLower.includes('loja') || mensagemLower.includes('sala')) tipo_imovel = 'comercial';

// Detectar localização
const bairros_comuns = [
  'centro', 'vila madalena', 'pinheiros', 'itaim', 'moema', 'vila olímpia',
  'brooklin', 'morumbi', 'jardins', 'perdizes', 'higienópolis', 'liberdade',
  'bela vista', 'consolação', 'santa cecília', 'república', 'sé'
];

let localizacao_detectada = null;
for (const bairro of bairros_comuns) {
  if (mensagemLower.includes(bairro)) {
    localizacao_detectada = bairro;
    break;
  }
}

// Detectar valores
const valores = mensagem.match(/\d{1,3}(?:\.\d{3})*(?:,\d{2})?/g);
let valor_detectado = null;
if (valores && valores.length > 0) {
  // Pegar o maior valor encontrado
  const valoresNumericos = valores.map(v => parseFloat(v.replace(/\./g, '').replace(',', '.')));
  valor_detectado = Math.max(...valoresNumericos);
}

return {
  json: {
    contexto_original: contexto,
    etapa_conversa: etapa_conversa,
    dados_coletados: dados_coletados,
    informacoes_detectadas: {
      tipo_imovel: tipo_imovel,
      localizacao: localizacao_detectada,
      valor: valor_detectado
    },
    cliente_existente: !!cliente,
    canal: canal
  }
};

// Gerar resposta baseada na etapa da conversa
const dados = $json;
const etapa = dados.etapa_conversa;
const informacoes = dados.informacoes_detectadas;
const dadosColetados = dados.dados_coletados;
const canal = dados.canal;

// Templates de resposta por etapa
const templates = {
  saudacao: {
    whatsapp: `Olá! 👋 Seja bem-vindo(a) à nossa imobiliária!

Sou seu assistente virtual e estou aqui para te ajudar a encontrar o imóvel ideal.

Para começar, me conta: você está buscando um imóvel para *comprar* ou *alugar*?`,
    email: `Olá!

Obrigado por entrar em contato conosco. Sou seu assistente virtual da imobiliária.

Para te ajudar da melhor forma, preciso saber: você está interessado em comprar ou alugar um imóvel?

Aguardo seu retorno!`
  },

  tipo_interesse: {
    whatsapp: `Perfeito! Entendi que você tem interesse em ${informacoes.tipo_imovel || 'um imóvel'}.

Agora me conta: que tipo de imóvel você está procurando?

🏠 Casa
🏢 Apartamento  
🏗️ Terreno
🏪 Comercial

É só me falar qual te interessa!`,
    email: `Obrigado pela informação!

Para prosseguir, preciso saber que tipo de imóvel você está buscando:

- Casa
- Apartamento
- Terreno
- Comercial

Por favor, me informe sua preferência.`
  },

  localizacao: {
    whatsapp: `Ótima escolha! ${dadosColetados.tipo_interesse === 'compra' ? 'Comprar' : 'Alugar'} um ${informacoes.tipo_imovel || 'imóvel'} é uma excelente decisão! 🎉

Agora preciso saber: *em qual região* você gostaria que fosse?

Pode me falar o bairro, zona ou até mesmo uma referência de localização que você prefere.`,
    email: `Excelente!

Para te apresentar as melhores opções, preciso saber em qual região você gostaria que o imóvel estivesse localizado.

Por favor, me informe o bairro ou zona de sua preferência.`
  },

  valor: {
    whatsapp: `Perfeito! Então você está buscando ${dadosColetados.tipo_interesse === 'compra' ? 'comprar' : 'alugar'} um ${informacoes.tipo_imovel || 'imóvel'} na região ${dadosColetados.localizacao_preferida || 'que você mencionou'}! 📍

Para te mostrar as opções que cabem no seu orçamento, qual seria o valor máximo que você gostaria de investir?

💰 Pode ser um valor aproximado mesmo!`,
    email: `Ótimo!

Para finalizar a qualificação e te apresentar as melhores opções dentro do seu orçamento, preciso saber qual seria o valor máximo que você gostaria de investir.

Por favor, me informe sua faixa de preço.`
  },

  nome_completo: {
    whatsapp: `Excelente! Já tenho todas as informações sobre o imóvel que você busca! ✅

📋 *Resumo:*
• Tipo: ${dadosColetados.tipo_interesse}
• Imóvel: ${informacoes.tipo_imovel || 'A definir'}
• Região: ${dadosColetados.localizacao_preferida}
• Valor: até R$ ${dadosColetados.valor_maximo ? dadosColetados.valor_maximo.toLocaleString('pt-BR') : 'A definir'}

Para finalizar seu cadastro e agendar uma visita, preciso do seu *nome completo*. Como posso te chamar?`,
    email: `Perfeito!

Já tenho todas as informações sobre suas preferências. Para finalizar seu cadastro e prosseguir com o atendimento, preciso apenas do seu nome completo.

Por favor, me informe como posso te chamar.`
  },

  dados_completos: {
    whatsapp: `Perfeito, ${dadosColetados.nome?.split(' ')[0]}! 🎉

Tenho aqui seu perfil completo:

📋 *Suas preferências:*
• Nome: ${dadosColetados.nome}
• Interesse: ${dadosColetados.tipo_interesse}
• Região: ${dadosColetados.localizacao_preferida}
• Valor: até R$ ${dadosColetados.valor_maximo?.toLocaleString('pt-BR')}

Vou buscar os imóveis disponíveis que combinam com o que você procura e em breve te envio as opções!

Enquanto isso, gostaria de agendar uma visita para conhecer pessoalmente alguns imóveis? 🏠`,
    email: `Obrigado, ${dadosColetados.nome}!

Seu perfil está completo e já estou buscando as melhores opções para você.

Em breve enviarei uma seleção de imóveis que atendem suas preferências. 

Gostaria de agendar uma visita presencial?`
  }
};

// Selecionar template baseado na etapa e canal
let resposta = templates[etapa]?.[canal] || templates[etapa]?.whatsapp || 'Desculpe, houve um erro. Pode repetir sua mensagem?';

// Personalizar resposta com informações detectadas
if (informacoes.tipo_imovel && etapa === 'saudacao') {
  resposta = resposta.replace('um imóvel', informacoes.tipo_imovel);
}

if (informacoes.localizacao && etapa === 'localizacao') {
  resposta += `\n\nVi que você mencionou ${informacoes.localizacao}. É essa região mesmo que te interessa?`;
}

if (informacoes.valor && etapa === 'valor') {
  resposta += `\n\nVi que você mencionou R$ ${informacoes.valor.toLocaleString('pt-BR')}. É essa sua faixa de orçamento?`;
}

// Determinar próxima ação
let proxima_acao = 'aguardar_resposta';
let transferir_para = null;

if (etapa === 'dados_completos') {
  proxima_acao = 'transferir_agendamento';
  transferir_para = 'Agendamento_Visitas';
}

return {
  json: {
    resposta: resposta,
    etapa_atual: etapa,
    proxima_acao: proxima_acao,
    transferir_para: transferir_para,
    dados_para_salvar: {
      ...dadosColetados,
      ...informacoes
    },
    contexto_completo: dados
  }
};
